***C.1. Import data
	forvalues year = 2013/2019 {
	import excel "../data/build_srm/srm_scbrand.xlsx", sheet("`year'") first clear
	gen year=`year'
	destring suppliercode, replace
	*only keep suppliercode with largest placedquantitiy
		egen largest = max(placedquantity), by(suppliercode)
		keep if largest==placedquantity
		drop largest
	save scbrand`year', replace
	}

***C.2. Append

use scbrand2013, clear
	forvalues year= 2014/2019 {
	append using scbrand`year'
	}

	forvalues year= 2013/2019 {
	erase scbrand`year'.dta
	}

order suppliercode year sc_* brand_* 
gen nonmissingsc = 0
replace nonmissingsc = 1 if !missing(sc_accessories)|!missing(sc_beauty)|!missing(sc_cosmetic)|!missing(sc_homehard)|!missing(sc_hometextile)|!missing(sc_jersey)|!missing(sc_knitted)|!missing(sc_nwswuw)|!missing(sc_shoes)|!missing(sc_socks)|!missing(sc_woven)
foreach var of varlist sc_* {
replace `var' = 0 if nonmissingsc == 1&missing(`var')
}
foreach var of varlist brand_* {
replace `var' = 0 if missing(`var')
}
drop nonmissingsc placedquantity

save ../data/build_srm/srm_scbrand, replace

	collapse (count) numorder = order (sum) onlyplaced onlyplan (mean) plantotal placedtotal, by(spurid year)

	* Now generate the annual measure of placed/plan
	gen placedminusplan = placedtotal - plantotal

	rename spurid spurid_s

	save ../data/build_other/planplaced_apparel, replace 



* Efficiency distributed across each PRODUCTION UNIT spurid
merge 1:m spurid_s year using  ../data/build_srm/supplier_pu_spurid_year
drop if _merge==2

order spurid_s year spurid
sort spurid_s year spurid
* browse

	save ../data/build_other/planplaced_pus, replace 

